/**
 * En MCP este estado vive en memoria de una librería SHAREDBYALL y lo comparten las copias del P080.
 * En Java las copias son instancias distintas: el estado se persiste para sobrevivir reinicios
 * y se protege con bloqueo optimista en lugar de INTERLOCK.
 */
@Entity @Table(name = "P080_ESTADO_CORTE")
public class EstadoCorteP080 {
    @Id private String programa = "P080";          // índice DF_IND_P080 = 0
    @Version private long version;                 // reemplaza LK_ESB_P080, LK_AVI_ABP080, LK_ASIGNA_NCOPIA

    private LocalDate fechaLineaB02;               // I_B02_FECHA_LINEA (de BD01)
    private LocalDate fechaLineaB07;               // I_B07_FECHA_LINEA (publicada a las copias)
    private LocalDate fechaLote;                   // I_B02_FECHA_LOTE
    private int csiEjecucion;                      // I_CSI_EJEC

    @Enumerated(EnumType.STRING)
    private FaseCorte fase = FaseCorte.LINEA;      // B_INIBATCHP080, B_INIBATCHP080_OK, B_BAJA_P080

    @ElementCollection
    private Map<Integer, CopiaP080> copias = new HashMap<>();   // IA_MIXES_XPGM, BA_COP_INIBATCH, BA_COP_AVISBAJA

    public enum FaseCorte { LINEA, CORTE_EN_CURSO, CORTE_OK, CORTE_FALLIDO, BAJA_EN_CURSO }
}

@Embeddable
public record CopiaP080(long mixId, boolean confirmoCorte, boolean confirmoBaja) {}
// Los EVENT E_INIBATCHP080, E_ESPERA_INIBATCHP080 y E_AVISO_P080 pasan a mensajes (ver s8).

# application.yml
l080:
  sistema: S500
  mtp: "002"
  copias-p080: 2              # DF_NUMCOPIAS_P080
  copias-max: 10              # DF_NUMCOPIAS_MAX
  bitacora:
    max-registros: 150        # DF_MAX_BIT
  datasources:
    bd01: s500-captacion      # (S500)S500BD01CAPTACION ON CAPTACION, solo lectura
    bd07: s500-atribucta      # (S500)S500BD07ATRIBUCTA ON CAPTACION

// ---------------------------------------------------------------------------
@ConfigurationProperties("l080")
@Validated
public record L080Properties(String sistema, String mtp,
                             @Min(1) @Max(10) int copiasP080, int copiasMax,
                             Bitacora bitacora, Map<String, String> datasources) {
    public record Bitacora(int maxRegistros) {}

    /** DF_HDRMSG(X): prefijo de todos los mensajes de consola. */
    public String encabezado(String codigo) { return sistema + "/L080/" + mtp + ":" + codigo; }
}

/** EXPORT: un método por entry point; las copias del P080 lo invocan por REST o gRPC. */
public interface CoordinadorP080 {
    ResultadoL080 inicioPorPrograma(RegistroCopia entrada, SalidaInicio salida);   // S500L080INICIOXPGM
    ResultadoL080 iniciaBatch();                                                  // S500L080INIBATCHP080
    ResultadoL080 esperaBatch(CopiaRef copia, SalidaEspera salida);               // S500L080ESBATCHP080
    ResultadoL080 avisoBaja(CopiaRef copia);                                      // S500L080AVIBAJAP080
    ResultadoL080 bitacora(RegistroBitacora registro);                            // S500L080BITACORA
    ResultadoL080 confirmaHi(ConfirmacionHi c);                                   // S500L080CONFIRMHI
    ResultadoL080 procesaHi(SolicitudHi s);                                       // S500L080PROCHI
}

@Component
@RequiredArgsConstructor
class CicloVidaL080 implements SmartLifecycle {
    private final ControlBd07Service control;
    private final BitacoraP080 bitacora;
    private final AtencionHiP080 atencionHi;
    private final EnvioArchivosLauncher envio;
    private volatile boolean activo;

    @Override public void start() {                // LEVANTA
        control.actualizaControl();               // ACT_CREA_CONTROL
        bitacora.abre();                          // ABRE_GENE_BITACORA
        atencionHi.inicia();                      // PROCESS HISP080
        activo = true;
    }
    @Override public void stop() {                // BAJA, al descongelarse la librería
        atencionHi.detiene();                     // CAUSE(E_FIN_HIP080) y espera a que termine
        bitacora.cierraConTrailer();
        envio.lanza(TipoEnvio.MONITOR);           // CALL_SYSTEM_WFL(1)
        envio.lanza(TipoEnvio.PROBLEMAS);         // CALL_SYSTEM_WFL(2)
        activo = false;
    }
    @Override public boolean isRunning() { return activo; }
}

@Service
@RequiredArgsConstructor
public class CorteLineaBatchService {

    private final ValidadorMixes mixes;            // VALIDA_IN_MIX
    private final ControlBd07Service control;      // ACTUALIZA_BD07
    private final BarreraCopias barrera;           // VALIDA_INIBATCH
    private final EnvioArchivos envio;             // ENVIO_ARCHIVOS
    private final EstadoCorteRepository estado;

    /** S500L080INIBATCHP080, bloque externo y TERMINAINIBATCHP080. */
    public ResultadoL080 iniciaBatch() {
        ResultadoL080 r = mixes.valida();
        if (r.ok()) r = control.copiaFechasABd07();
        if (r.ok()) r = barrera.esperaConfirmaciones(Duration.ofMinutes(2));

        var e = estado.actual();
        if (r.ok()) {
            envio.cierraBitacoraYEnvia();          // trailer, WFL 1 y 2, nueva bitácora
            e.publicaFechaLinea(e.fechaLineaB02()); // I_B07_FECHA_LINEA := I_B02_FECHA_LINEA
            e.fase(FaseCorte.CORTE_OK);
        } else {
            e.fase(FaseCorte.CORTE_FALLIDO);
        }
        barrera.liberaCopias(e);                   // CAUSE(E_ESPERA_INIBATCHP080), en cualquier caso
        return r;
    }
}

@Service
@RequiredArgsConstructor
class ControlBd07Service {

    private final ControlBd01Repository bd01;    // S500B02CONTROL de BD01, solo lectura
    private final ControlBd07Repository bd07;    // S500B02CONTROL de BD07
    private final CsiComs coms;                  // OBTIENE_CSI_COMS

    /** ACTUALIZA_BD07: una sola transacción; cualquier error hace rollback y regresa 14. */
    @Transactional("bd07TransactionManager")
    public ResultadoL080 copiaFechasABd07() {
        try {
            var origen = bd01.findFirst().orElseThrow();
            var destino = bd07.findByTipoRegistro(1)
                    .orElseGet(() -> ControlB02.nuevo(1, coms.csiEjecucion()));   // CREATE con B02-NUM-CSI
            destino.setFechaLinea(origen.getFechaLinea());
            destino.setFechaLote(origen.getFechaLote());
            bd07.saveAndFlush(destino);                // STORE; el fuente cierra con ENDTRANSACTION AUDIT ... SYNC
            return ResultadoL080.OK;
        } catch (DataAccessException | NoSuchElementException e) {
            log.error("ERROR DMSII BASE: S500BD07ATRIBUCTA", e);
            TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
            return ResultadoL080.ERROR_BASE_DATOS;     // DF_ERRORDB_RSLT: I_RESULT := 14
        }
    }
}

@Component
@RequiredArgsConstructor
class BarreraCopias {

    private final ComandosP080 comandos;          // ENVIO_HI
    private final EstadoCorteRepository estado;

    /** VALIDA_INIBATCH: HI 4030 a todas las copias y espera a que todas confirmen. */
    ResultadoL080 esperaConfirmaciones(Duration limite) {
        var e = estado.actual();
        e.iniciaCorte();                           // B_INIBATCHP080 := TRUE, OK := FALSE, RESET evento
        estado.save(e);
        comandos.envia(Hi.CAMBIO_A_BATCH);         // HI 4030

        Instant fin = Instant.now().plus(limite);  // 12 x WAITANDRESET((10)) = 120 s
        while (Instant.now().isBefore(fin)) {
            if (estado.actual().todasConfirmaronCorte()) {
                estado.actual().limpiaConfirmacionesCorte();   // BA_COP_INIBATCH := FALSE
                return ResultadoL080.OK;
            }
            esperaEvento(Duration.ofSeconds(10));  // notificación de confirmación o timeout
        }
        estado.actual().limpiaConfirmacionesCorte();
        return ResultadoL080.COPIA_SIN_CONFIRMAR_CAMBIO;     // 7
    }
}

@Service
@RequiredArgsConstructor
class EsperaBatchService {

    private final EstadoCorteRepository estado;
    private final ValidadorCopias validador;           // VALIDA_PMC
    private final L080Properties props;

    /** S500L080ESBATCHP080: la copia confirma y queda en espera hasta el fin del corte. */
    @Transactional
    public ResultadoL080 esperaBatch(CopiaRef copia, SalidaEspera salida) {
        var e = estado.findForUpdate();                // LOCK(LK_ESB_P080)
        if (e.fase() != FaseCorte.CORTE_EN_CURSO) {
            return ResultadoL080.AUN_NO_INICIA_BATCH;  // 8
        }
        ResultadoL080 r = validador.valida(copia.paso(), copia.mix(), copia.numero());
        if (!r.ok()) return r;
        e.confirmaCorte(copia.numero());               // BA_COP_INIBATCH[..] := TRUE y CAUSE(E_INIBATCHP080)
        return ResultadoL080.PENDIENTE;                // la respuesta final llega por mensaje (ver racional)
    }

    /** Al recibir la liberación: WAIT (E_ESPERA_INIBATCHP080) ya no bloquea un hilo. */
    @KafkaListener(topics = "p080.corte.liberacion")
    void alLiberar(LiberacionCorte msg, CopiaLocal copiaLocal) {
        if (msg.fase() == FaseCorte.CORTE_OK) copiaLocal.usaFechaLinea(msg.fechaLinea());
        else copiaLocal.marcaError(ResultadoL080.ERROR_EN_BATCH);   // 10
    }
}

/** Códigos HI que L080 envía a las copias del P080. */
public enum Hi {
    CAMBIO_A_BATCH(4030), AVISO_BAJA(4038), BAJA_FORZADA(4040);
    final int codigo;
    Hi(int c) { codigo = c; }
}

@Component
@RequiredArgsConstructor
class ComandosP080 {

    private final KafkaTemplate<String, ComandoCopia> kafka;
    private final EstadoCorteRepository estado;

    /** ENVIO_HI: arma "mix mix ... HI nnnn" y lo teclea en la consola del MCP con DCKEYIN. */
    void envia(Hi hi) {
        var copias = estado.actual().copiasActivas();     // IA_MIXES_XPGM[..] > 0
        if (copias.isEmpty()) return;                    // OFFSET(P_EA_RSPO) = 0: no se envía nada
        copias.forEach(c -> kafka.send("p080.comandos", String.valueOf(c.mixId()),
                                        new ComandoCopia(c.mixId(), hi.codigo)));
    }
}

@Service
@RequiredArgsConstructor
class BajaOrdenadaService {

    private static final Duration ESPERA_POR_HI = Duration.ofMinutes(2);   // (I_WAIT_TIMES * 5) > 119
    private final ComandosP080 comandos;
    private final EstadoCorteRepository estado;

    /** AVISO_BAJAP080: solo escala a 4040 si con 4038 no confirmaron todas. */
    ResultadoL080 avisoBaja() {
        ResultadoL080 r = ResultadoL080.OK;
        for (Hi hi : List.of(Hi.AVISO_BAJA, Hi.BAJA_FORZADA)) {
            comandos.envia(hi);
            if (esperaConfirmacionesBaja(ESPERA_POR_HI)) { r = ResultadoL080.OK; break; }
            r = ResultadoL080.COPIA_SIN_CONFIRMAR_BAJA;      // 12
        }
        estado.actual().limpiaConfirmacionesBaja();          // BA_COP_AVISBAJA := FALSE, B_BAJA_P080 := FALSE
        return r;
    }

    private boolean esperaConfirmacionesBaja(Duration limite) {
        Instant fin = Instant.now().plus(limite);
        while (Instant.now().isBefore(fin)) {
            if (estado.actual().todasConfirmaronBaja()) return true;
            esperaEvento(Duration.ofSeconds(5));             // WAITANDRESET((5),E_AVISO_P080)
        }
        return false;
    }
}

@Component
@RequiredArgsConstructor
class EnvioArchivosLauncher {

    private final JobLauncher launcher;
    private final Map<TipoEnvio, Job> jobs;       // ENVIAMONIP080, ENVIAPROBP080, ENVIABITAP080
    private final EstadoCorteRepository estado;

    /** CALL_SYSTEM_WFL(I_ENVIO): START S500JBATCH("ENVIAxxxP080 aaaammdd"). */
    void lanza(TipoEnvio tipo) {
        var params = new JobParametersBuilder()
                .addLocalDate("fechaLinea", estado.actual().fechaLineaB07())
                .addString("envio", tipo.nombreWfl())
                .toJobParameters();
        try {
            launcher.run(jobs.get(tipo), params);
        } catch (JobExecutionException e) {
            log.error("ERROR AL LANZAR {}", tipo.nombreWfl(), e);   // el ZIP del fuente no revisa el resultado
        }
    }
    // Las credenciales del job se resuelven con la identidad de servicio del orquestador
    // (Vault o el secreto de Kubernetes), nunca en el código.
}

public enum TipoEnvio {
    MONITOR("ENVIAMONIP080"), PROBLEMAS("ENVIAPROBP080"), BITACORA("ENVIABITAP080");
    private final String wfl;
    TipoEnvio(String w) { wfl = w; }
    String nombreWfl() { return wfl; }
}
